-- #987 wave 1 (pure additions): Darkshore creature abilities, imported from DeltaTho PR 15 file 2026_10_24_19_world.sql.
-- 73 creatures, 159 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '2172,2175,2184,2186,2191,2192,2206,2233,7015,7016,7017,32855,32858,32859,32860,32861,32862,32863,32868,32869,32888,32899,32928,32935,32969,32988,32989,32990,32996,33009,33020,33021,33022,33057,33071,33079,33083,33084,33107,33115,33117,33127,33179,33180,33181,33206,33207,33311,33345,33359,33864,33905,33978,33981,34009,34033,34046,34056,34248,34302,34304,34309,34326,34331,34339,34385,34405,34413,34414,34417,34427,43440,48763';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
